export function CommandersGallery(n){return`<div class="commanders-grid">${n.map(n=>{const a=n.battles.map(n=>`<li>${n}</li>`).join("");return`\n            <div class="commander-card" style="--cmd-color: ${n.color}">\n                <div class="commander-avatar" style="background: ${n.color}">\n                    ${n.name.split(" ").map(n=>n[0]).join("")}\n                </div>\n                <div class="commander-info">\n                    <h4>${n.name}</h4>\n                    <p class="commander-title">${n.title}</p>\n                    <span class="commander-era">${n.era}</span>\n                    <p class="commander-desc">${n.description}</p>\n                    <div class="commander-battles">\n                        <span class="cb-label">Battles:</span>\n                        <ul>${a}</ul>\n                    </div>\n                </div>\n            </div>\n        `}).join("")}</div>`}